using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;using Qms.Domain.RiskManagement;
namespace Qms.Infrastructure.Persistence.Configurations;
public sealed class RiskAssessmentConfiguration:IEntityTypeConfiguration<RiskAssessment>{public void Configure(EntityTypeBuilder<RiskAssessment>b){b.ToTable("risk_assessment","risk_management");b.HasKey(x=>x.Id);b.Property(x=>x.Process).HasMaxLength(240).IsRequired();b.Property(x=>x.Scope).HasMaxLength(6000).IsRequired();b.Property(x=>x.Category).HasMaxLength(80).IsRequired();b.Property(x=>x.Methodology).HasMaxLength(80).IsRequired();b.Property(x=>x.MatrixVersion).HasMaxLength(80).IsRequired();b.Property(x=>x.Owner).HasMaxLength(200).IsRequired();b.Property(x=>x.OwnerDepartment).HasMaxLength(160);b.Property(x=>x.Approver).HasMaxLength(200).IsRequired();b.Property(x=>x.Status).HasConversion<string>().HasMaxLength(40);b.Property(x=>x.Version).IsConcurrencyToken();b.HasIndex(x=>x.QualityRecordId).IsUnique();b.HasOne<Qms.Domain.QualityRecords.QualityRecord>().WithMany().HasForeignKey(x=>x.QualityRecordId).OnDelete(DeleteBehavior.Restrict);b.HasOne<Qms.Infrastructure.Identity.ApplicationUser>().WithMany().HasForeignKey(x=>x.OwnerUserId).OnDelete(DeleteBehavior.Restrict);b.HasOne<Qms.Infrastructure.Identity.ApplicationUser>().WithMany().HasForeignKey(x=>x.ApproverUserId).OnDelete(DeleteBehavior.Restrict);b.HasMany(x=>x.Items).WithOne().HasForeignKey(x=>x.RiskAssessmentId).OnDelete(DeleteBehavior.Cascade);b.Navigation(x=>x.Items).UsePropertyAccessMode(PropertyAccessMode.Field);}}
public sealed class RiskItemConfiguration:IEntityTypeConfiguration<RiskItem>{public void Configure(EntityTypeBuilder<RiskItem>b){b.ToTable("risk_item","risk_management");b.HasKey(x=>x.Id);b.Property(x=>x.FailureMode).HasMaxLength(1000).IsRequired();b.Property(x=>x.Effect).HasMaxLength(2000).IsRequired();b.Property(x=>x.Cause).HasMaxLength(2000).IsRequired();b.Property(x=>x.ExistingControls).HasMaxLength(3000).IsRequired();b.Property(x=>x.Action).HasMaxLength(3000);b.Property(x=>x.ActionOwner).HasMaxLength(200);b.Property(x=>x.ActionEvidence).HasMaxLength(6000);b.Property(x=>x.ResidualRationale).HasMaxLength(3000);b.Property(x=>x.Status).HasConversion<string>().HasMaxLength(40);b.HasOne<Qms.Infrastructure.Identity.ApplicationUser>().WithMany().HasForeignKey(x=>x.ActionOwnerUserId).OnDelete(DeleteBehavior.Restrict);}}
public sealed class RiskLookupDefinitionConfiguration:IEntityTypeConfiguration<RiskLookupDefinition>{public void Configure(EntityTypeBuilder<RiskLookupDefinition>b){b.ToTable("lookup_definition","risk_management");b.HasKey(x=>x.Id);b.Property(x=>x.Category).HasMaxLength(40).IsRequired();b.Property(x=>x.Code).HasMaxLength(80).IsRequired();b.Property(x=>x.Name).HasMaxLength(160).IsRequired();b.HasIndex(x=>new{x.Category,x.Code}).IsUnique();}}
